<?php
declare(strict_types=1);session_start();require_once __DIR__ . '/config/product_step11.php';
function ob_price(array $r,string $tier):?float{if($tier==='MRP')return(float)$r['mrp'];return array_key_exists($tier,$r['tiers'])?(float)$r['tiers'][$tier]:null;}
if(empty($_SESSION['product_order_csrf']))$_SESSION['product_order_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['product_order_csrf'];if(!isset($_SESSION['product_cart'])||!is_array($_SESSION['product_cart']))$_SESSION['product_cart']=[];$cart=&$_SESSION['product_cart'];$error=null;$success=null;$rows=[];$byId=[];$tier=(string)($_REQUEST['tier']??($_SESSION['product_tier']??'PC_GOLD'));$mode=(string)($_REQUEST['mode']??($_SESSION['product_order_mode']??'pickup'));$allowed=['MRP','PC_BRONZE','PC_SILVER','PC_GOLD','ASSOC_RETAIL','ASSOC_EARN_BASE','ASSOC_25','ASSOC_35','ASSOC_42','ASSOC_50','PU_PRICE'];if(!in_array($tier,$allowed,true))$tier='PC_GOLD';if(!in_array($mode,['pickup','delivery'],true))$mode='pickup';$_SESSION['product_tier']=$tier;$_SESSION['product_order_mode']=$mode;$tierLabels=['MRP'=>'MRP','PC_BRONZE'=>'Preferred Bronze','PC_SILVER'=>'Preferred Silver','PC_GOLD'=>'Preferred Gold','ASSOC_RETAIL'=>'Associate Retail','ASSOC_EARN_BASE'=>'Earn Base','ASSOC_25'=>'Associate 25%','ASSOC_35'=>'Senior Consultant 35%','ASSOC_42'=>'Qualified Producer / Success Builder 42%','ASSOC_50'=>'Supervisor 50%','PU_PRICE'=>'PU Price'];
try{$pdo=business_db();product_step11_ensure($pdo);$ctx=product_org_context($pdo);$orgId=(int)$ctx['organization_id'];$market=product_step11_market($pdo,$orgId);$marketId=(int)$market['id'];$rows=product_step11_catalog_rows($pdo,$orgId);foreach($rows as $r)$byId[(int)$r['id']]=$r;if(isset($_GET['add'])&&is_numeric($_GET['add'])){$id=(int)$_GET['add'];if(isset($byId[$id]))$cart[$id]=max(1,(int)($cart[$id]??0)+1);}if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'update');if($action==='clear')$cart=[];elseif($action==='update'){foreach((array)($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$q=max(0,min(999,(int)$qty));if($q===0)unset($cart[$id]);elseif(isset($byId[$id]))$cart[$id]=$q;}}elseif($action==='save_quote'&&!$cart)throw new RuntimeException('Add at least one product before saving a quote.');}}catch(Throwable $e){$error=$e->getMessage();}
$items=[];$invalid=[];$subtotal=0.0;$payable=0.0;$vp=0.0;$hasNutrition=false;foreach($cart as $id=>$qty){if(!isset($byId[$id]))continue;$r=$byId[$id];$price=ob_price($r,$tier);if($price===null){$invalid[]=$r+['qty'=>$qty];continue;}$lineMrp=(float)$r['mrp']*$qty;$linePrice=$price*$qty;$lineVp=(float)$r['volume_points']*$qty;$subtotal+=$lineMrp;$payable+=$linePrice;$vp+=$lineVp;if(!in_array((string)$r['category_name'],['ART OF PROMOTION','APPLICATIONS'],true))$hasNutrition=true;$items[]=$r+['qty'=>$qty,'unit_price'=>$price,'line_mrp'=>$lineMrp,'line_price'=>$linePrice,'line_vp'=>$lineVp];}
$delivery=($mode==='delivery'&&$hasNutrition&&$vp<100&&$vp>0)?100.0:0.0;$saving=max(0,$subtotal-$payable);$grand=$payable+$delivery;
if(!$error&&$_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_quote'){try{if($invalid)throw new RuntimeException('Quote cannot be saved because '.count($invalid).' selected item(s) do not have a source-listed '.$tierLabels[$tier].' price. Remove them or choose an applicable tier.');$pdo->beginTransaction();$code='Q'.date('YmdHis').'-'.random_int(100,999);$stmt=$pdo->prepare("INSERT INTO product_quotes(organization_id,market_id,quote_code,customer_name,customer_type,pricing_tier_code,subtotal_mrp,payable_amount,saving_amount,total_vp,delivery_charge,grand_total,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'saved',?)");$stmt->execute([$orgId,$marketId,$code,trim((string)($_POST['customer_name']??''))?:null,str_starts_with($tier,'PC_')?'preferred':'associate',$tier,$subtotal,$payable,$saving,$vp,$delivery,$grand,trim((string)($_POST['notes']??''))?:null]);$quoteId=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO product_quote_items(quote_id,product_id,listing_id,price_version_id,stock_no,product_name,quantity,unit_mrp,unit_price,unit_vp,line_mrp,line_price,line_vp) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)");foreach($items as $it)$ins->execute([$quoteId,(int)$it['id'],(int)$it['listing_id'],(int)$it['price_version_id'],$it['sku'],$it['product_name'],$it['qty'],$it['mrp'],$it['unit_price'],$it['volume_points'],$it['line_mrp'],$it['line_price'],$it['line_vp']]);if(business_table_exists($pdo,'audit_logs')){$a=$pdo->prepare("INSERT INTO audit_logs(organization_id,event_type,entity_type,entity_id,details_json) VALUES(?,'product_quote_saved','product_quote',?,?)");$a->execute([$orgId,$quoteId,json_encode(['quote_code'=>$code,'tier'=>$tier,'items'=>count($items),'grand_total'=>$grand],JSON_UNESCAPED_SLASHES)]);}$pdo->commit();$success='Quote '.$code.' saved successfully.';}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Product Order Builder - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="product_catalog.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Product & Price Pro • Order Calculator</small></span></a><div class="os-top-actions"><a class="os-btn" href="product_catalog.php">+ Browse Products</a><a class="os-btn" href="product_quotes.php">Saved Quotes</a><button class="os-btn" onclick="window.print()">Print / Save PDF</button><a class="os-btn primary" href="index.php">Dashboard</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Product System</div><nav class="os-nav"><a href="product_catalog.php"><i class="dot"></i>Catalog</a><a class="active" href="product_order_builder.php"><i class="dot"></i>Order Builder</a><a href="product_compare.php"><i class="dot"></i>Compare</a><a href="product_favorites.php"><i class="dot"></i>Favorites</a><a href="product_quotes.php"><i class="dot"></i>Saved Quotes</a><a href="product_price_history.php"><i class="dot"></i>Price History</a><a href="product_audit.php"><i class="dot"></i>STEP 11 Audit</a></nav><div class="os-sidebar-status"><b>Source-exact calculator</b><span>Missing tier prices are blocked instead of falling back to another price.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 11 • Order Builder</div><h1>Build an order and calculate MRP, payable amount, saving, VP and delivery in real time.</h1><p>Select a source-listed Preferred or Associate pricing level, change quantities and save a traceable quote. Items without that exact tier are clearly marked and excluded until corrected.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'ORDER BUILDER LIVE':'Review required' ?></span><span class="os-chip"><?= number_format(count($items)) ?> priced items</span><span class="os-chip <?= $invalid?'':'good' ?>"><?= number_format(count($invalid)) ?> unlisted-tier items</span><span class="os-chip"><?= product_h($tierLabels[$tier]) ?></span><span class="os-chip"><?= product_h(strtoupper($mode)) ?></span></div></section><?php if($success):?><div class="pp-alert good"><?= product_h($success) ?></div><?php endif;?><?php if($error):?><div class="pp-alert bad"><?= product_h($error) ?></div><?php endif;?><?php if($invalid):?><div class="pp-alert bad"><strong>Pricing incomplete:</strong> <?= count($invalid) ?> selected item(s) have no <?= product_h($tierLabels[$tier]) ?> value in the reviewed source. They are not included in totals.</div><?php endif;?>
<section class="os-card" style="margin-top:14px"><form method="get" class="pp-toolbar"><input value="<?= number_format(count($cart)) ?> products selected" readonly><select name="tier"><?php foreach($tierLabels as $k=>$v):?><option value="<?= product_h($k) ?>" <?= $tier===$k?'selected':'' ?>><?= product_h($v) ?></option><?php endforeach;?></select><select name="mode"><option value="pickup" <?= $mode==='pickup'?'selected':'' ?>>Pickup</option><option value="delivery" <?= $mode==='delivery'?'selected':'' ?>>Home Delivery / Ecom Drop Point</option></select><button>Update Pricing →</button></form></section><section class="pp-order-layout"><article class="os-card pp-order-list"><div class="os-title-row"><div><h2>Products & Quantities</h2><p>“Not listed” means this exact tier is absent from the PDF for that item.</p></div></div><form method="post"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="update"><input type="hidden" name="tier" value="<?= product_h($tier) ?>"><input type="hidden" name="mode" value="<?= product_h($mode) ?>"><?php foreach($rows as $r):$qty=(int)($cart[(int)$r['id']]??0);$price=ob_price($r,$tier);?><div class="pp-order-item"><div><b><?= product_h($r['sku'].' • '.$r['product_name']) ?></b><small><?= product_h($r['category_name']) ?><?= $price===null?' • NOT LISTED AT THIS TIER':'' ?></small></div><input type="number" min="0" max="999" name="qty[<?= (int)$r['id'] ?>]" value="<?= $qty ?>" aria-label="Quantity"><span class="price-col"><?= $price===null?'—':'₹'.number_format($price,2) ?></span><span class="hide-mobile"><?= product_h(rtrim(rtrim(number_format((float)$r['volume_points'],3,'.',''),'0'),'.')) ?> VP</span><span class="hide-mobile">MRP ₹<?= number_format((float)$r['mrp'],0) ?></span></div><?php endforeach;?><div class="pp-actions"><button class="primary">Recalculate</button></div></form></article><aside class="os-card pp-order-summary"><h2>Order Summary</h2><div class="pp-total"><span>MRP Total</span><strong>₹<?= number_format($subtotal,2) ?></strong></div><div class="pp-total"><span>Payable</span><strong>₹<?= number_format($payable,2) ?></strong></div><div class="pp-total"><span>Saving</span><strong>₹<?= number_format($saving,2) ?></strong></div><div class="pp-total"><span>Total VP</span><strong><?= product_h(rtrim(rtrim(number_format($vp,3,'.',''),'0'),'.')) ?></strong></div><div class="pp-total"><span>Delivery</span><strong>₹<?= number_format($delivery,2) ?></strong></div><div class="pp-total pp-grand"><span>Grand Total</span><strong>₹<?= number_format($grand,2) ?></strong></div><?php if($mode==='delivery'&&$delivery>0):?><div class="pp-alert" style="background:#fff7ea;color:#805a20">Below 100 VP: ₹100 delivery charge excluding taxes is applied from the PDF rule.</div><?php endif;?><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="save_quote"><input type="hidden" name="tier" value="<?= product_h($tier) ?>"><input type="hidden" name="mode" value="<?= product_h($mode) ?>"><label>Customer / Quote Name<input name="customer_name" placeholder="Optional"></label><label>Notes<textarea name="notes" placeholder="Optional quote note"></textarea></label><button <?= (!$items||$invalid)?'disabled':'' ?>>Save Quote</button></form><form method="post" style="margin-top:8px"><input type="hidden" name="csrf" value="<?= product_h($csrf) ?>"><input type="hidden" name="action" value="clear"><button class="os-btn" style="width:100%">Clear Order</button></form></aside></section></main></div></body></html>